import{c as i,U as s,j as n,g as t,o,a6 as l,n as r}from"./chunks/framework.h4W4t1IS.js";const q=JSON.parse('{"title":"Auto-évaluation et revue de code","description":"","frontmatter":{"title":"Auto-évaluation et revue de code","status":"ready","tags":["auto-evaluation","all"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"pratiques/auto-evaluation.md","filePath":"pratiques/auto-evaluation.md"}'),u={name:"pratiques/auto-evaluation.md"},c={id:"frontmatter-title",tabindex:"-1"};function d(a,e,p,m,f,h){return s(),n("div",null,[t("h1",c,[o(l(a.$frontmatter.title)+" ",1),e[0]||(e[0]=t("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=r('<p>L&#39;<strong>auto-évaluation</strong> et la <strong><a href="/420-w30-sf-po2/lexique.html#revue-de-code" class="lexicon-link" title="Examen du code d&#39;un pair avant intégration : lire les tests d&#39;abord, vérifier les conventions et les principes SOLID, commenter précisément et de façon constructive.">revue de code</a> par les pairs</strong> sont deux pratiques professionnelles qui améliorent la qualité du code et accélèrent l&#39;apprentissage.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Appliquer une grille d&#39;auto-évaluation avant de soumettre un travail</li><li>Effectuer une revue de code constructive sur le code d&#39;un pair</li><li>Identifier les critères d&#39;un code de qualité</li></ul></div><h2 id="auto-evaluation-avant-de-soumettre" tabindex="-1">Auto-évaluation - avant de soumettre <a class="header-anchor" href="#auto-evaluation-avant-de-soumettre" aria-label="Permalink to &quot;Auto-évaluation - avant de soumettre&quot;">​</a></h2><p>Avant de remettre un travail, se poser ces questions :</p><h3 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h3><ul><li>[ ] Tous les tests passent</li><li>[ ] Les tests couvrent les cas normaux, limites et d&#39;erreur</li><li>[ ] Les noms de tests suivent la convention <code>étantDonneLorsqueAlors</code></li><li>[ ] Le <a href="/420-w30-sf-po2/lexique.html#aaa" class="lexicon-link" title="Structure en trois étapes d&#39;un test : Arrange (préparer l&#39;état), Act (exécuter l&#39;action testée), Assert (vérifier le résultat). Correspond à Étant donné/Lorsque/Alors dans le nommage.">patron AAA</a> est respecté</li><li>[ ] Chaque test a au moins une assertion pertinente</li><li>[ ] Pas de logique conditionnelle dans les tests</li></ul><h3 id="code-de-production" tabindex="-1">Code de production <a class="header-anchor" href="#code-de-production" aria-label="Permalink to &quot;Code de production&quot;">​</a></h3><ul><li>[ ] Les méthodes publiques valident leurs <a href="/420-w30-sf-po2/lexique.html#precondition" class="lexicon-link" title="Condition qui doit être vraie avant l&#39;exécution d&#39;une méthode ou d&#39;une fonction pour garantir son bon fonctionnement.">préconditions</a></li><li>[ ] Aucune <a href="/420-w30-sf-po2/lexique.html#valeur-magique" class="lexicon-link" title="Valeur codée en dur dans le code source, souvent utilisée pour représenter des constantes ou des paramètres spécifiques. L&#39;utilisation de valeurs magiques est déconseillée, car elles rendent le code moins lisible et plus difficile à maintenir.">valeur magique</a> (utiliser des constantes)</li><li>[ ] Nommage clair et descriptif (pas d&#39;abréviations)</li><li>[ ] Pas de connaissance dupliquée (<a href="/420-w30-sf-po2/lexique.html#don-t-repeat-yourself" class="lexicon-link" title="Principe de développement qui encourage la réduction de la duplication d&#39;informations, favorisant la réutilisation et la maintenabilité en centralisant la connaissance.">DRY</a>)</li><li>[ ] Chaque classe a une responsabilité claire (<a href="/420-w30-sf-po2/lexique.html#responsabilite-unique" class="lexicon-link" title="Principe SOLID qui stipule qu&#39;une classe ne devrait avoir qu&#39;une seule raison de changer.">SRP</a>)</li></ul><h3 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h3><ul><li>[ ] Les dépendances respectent les contraintes <a href="/420-w30-sf-po2/lexique.html#mvc" class="lexicon-link" title="Patron architectural en trois couches : le modèle (domaine, ignore tout du reste), la vue (affiche des DTOs, ignore le modèle), le contrôleur (orchestre les deux, connaît modèle ET vue).">MVC</a></li><li>[ ] Les <a href="/420-w30-sf-po2/lexique.html#interface" class="lexicon-link" title="Contrat qui définit un ensemble de méthodes qu&#39;une classe doit implémenter, sans fournir d&#39;implémentation concrète. Permet de définir des comportements communs pour différentes classes.">interfaces</a> sont utilisées pour les dépendances injectées</li><li>[ ] Les <a href="/420-w30-sf-po2/lexique.html#dto" class="lexicon-link" title="Objet immuable dont le seul rôle est de transporter des données entre les couches (souvent modèle ↔ vue), sans comportement. Créé et transformé par un convertisseur.">DTOs</a> ne contiennent pas de comportements</li></ul>',11))])}const x=i(u,[["render",d]]);export{q as __pageData,x as default};
